const GOOGLE_MAPS_API_KEY = process.env.GOOGLE_MAPS_PLATFORM_KEY || "";
const hasValidMapsKey =
  Boolean(GOOGLE_MAPS_API_KEY) && GOOGLE_MAPS_API_KEY !== "YOUR_API_KEY";

const calculateDistance = (
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number,
) => {
  const R = 6371e3; // metres
  const φ1 = (lat1 * Math.PI) / 180;
  const φ2 = (lat2 * Math.PI) / 180;
  const Δφ = ((lat2 - lat1) * Math.PI) / 180;
  const Δλ = ((lon2 - lon1) * Math.PI) / 180;

  const a =
    Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
    Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  const d = R * c; // in metres
  return d;
};

const LiveLocationMap = ({
  userLat,
  userLng,
  projectLat,
  projectLng,
  radius = 500,
}: {
  userLat: number;
  userLng: number;
  projectLat: number;
  projectLng: number;
  radius?: number;
}) => {
  if (!hasValidMapsKey) return null;

  return (
    <div className="w-full h-[220px] rounded-[2.5rem] overflow-hidden shadow-inner border-4 border-white mt-2 bg-slate-50 relative">
      <APIProvider apiKey={GOOGLE_MAPS_API_KEY}>
        <GoogleMap
          defaultCenter={{
            lat: (userLat + projectLat) / 2,
            lng: (userLng + projectLng) / 2,
          }}
          defaultZoom={14}
          mapId="DEMO_MAP_ID"
          gestureHandling={"greedy"}
          internalUsageAttributionIds={["gmp_mcp_codeassist_v1_aistudio"]}
          style={{ width: "100%", height: "100%" }}
          disableDefaultUI={true}
        >
          <AdvancedMarker
            position={{ lat: userLat, lng: userLng }}
            title="Posisi Anda"
          >
            <div className="relative">
              <div
                className={`absolute -inset-8 rounded-full animate-pulse transition-colors ${calculateDistance(userLat, userLng, projectLat, projectLng) <= radius ? "bg-emerald-500/20" : "bg-rose-500/20"}`}
              />
              <Pin
                background={
                  calculateDistance(userLat, userLng, projectLat, projectLng) <=
                  radius
                    ? "#10b981"
                    : "#ef4444"
                }
                glyphColor="#fff"
              />
            </div>
          </AdvancedMarker>
          <AdvancedMarker
            position={{ lat: projectLat, lng: projectLng }}
            title="Titik Projek"
          >
            <Pin background="#3b82f6" glyphColor="#fff" />
          </AdvancedMarker>
        </GoogleMap>
      </APIProvider>
    </div>
  );
};

