  useEffect(() => {
    if (!currentUser || currentUser.role === "admin" || currentUser.role === "owner" || currentUser.role === "direktur") return;

    const checkTime = () => {
      const now = new Date();
      const hours = now.getHours();
      const minutes = now.getMinutes();
      const timeStr = `${hours.toString().padStart(2, "0")}:${minutes.toString().padStart(2, "0")}`;

      // Morning reminder (08:50 - 09:00)
      if (hours === 8 && minutes >= 50 && !isClockedIn && !isClockedOut) {
        if (showAttendanceReminder !== "IN") setShowAttendanceReminder("IN");
      }
      // Afternoon reminder (16:50 - 17:00)
      else if (hours === 16 && minutes >= 50 && isClockedIn && !isClockedOut) {
        if (showAttendanceReminder !== "OUT") setShowAttendanceReminder("OUT");
      } else {
        // Reset if outside window
        if (showAttendanceReminder) setShowAttendanceReminder(null);
      }
    };

    checkTime();
    const interval = setInterval(checkTime, 60000); // Check every minute
    return () => clearInterval(interval);
  }, [currentUser, isClockedIn, isClockedOut, showAttendanceReminder]);

