  const handleConvertQuotationToProject = async (q: Quotation) => {
    const projectExists = projects.some(p => 
      p.name === q.jobDescription || 
      (p.description && p.description.includes(q.number))
    );

    if (projectExists) {
      alert("Proyek untuk Surat Penawaran ini sudah terdaftar di Manajemen Proyek sebelumnya.");
      return;
    }

    const confirmConvert = window.confirm(
      `Apakah Anda yakin ingin menaikkan Surat Penawaran No: ${q.number} menjadi Proyek Resmi dan langsung mendaftarkannya ke Manajemen Proyek?`
    );
    if (!confirmConvert) return;

    const projectId = `PRJ-${Math.floor(1000 + Math.random() * 9000)}`;
    const newProject: Project = {
      id: projectId,
      name: q.jobDescription,
      location: q.recipient,
      startDate: new Date().toISOString().split("T")[0],
      endDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
      status: "SPK/PO Diterima",
      priority: "Medium",
      progress: 0,
      manager: "Unassigned",
      managerId: "",
      managerName: "Unassigned",
      picId: "",
      picName: "Unassigned",
      description: `Proyek otomatis dari Surat Penawaran berkas No: ${q.number}\n\nPenerima: ${q.recipient}\nPerhatian: ${q.attention}`,
      tasks: [],
      contractValue: q.grandTotal,
      totalInvoices: 0,
      totalPaid: 0,
      remainingReceivables: q.grandTotal,
      totalCost: 0,
      profit: q.grandTotal,
      operationalCost: 0,
      timeline: [
        {
          id: `TL-INIT-${Date.now()}`,
          date: new Date().toISOString().split("T")[0],
          time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
          user: currentUser?.name || "Sistem",
          status: "SPK/PO Diterima",
          notes: `Proyek otomatis dibuat via konversi Surat Penawaran resmi No: ${q.number}. Nilai Kontrak: Rp ${q.grandTotal.toLocaleString("id-ID")}`
        }
      ],
      uploadedDocuments: [
        {
          id: `DOC-QT-${Date.now()}`,
          name: `Surat Penawaran No ${q.number}`,
          type: "Lainnya",
          uploadedAt: new Date().toISOString(),
          uploadedBy: currentUser?.name || "Sistem",
          fileUrl: "",
          status: "Approved",
        }
      ],
      schedules: [],
      paymentTerms: [],
    };

    try {
      await dbService.setDocument("projects", projectId, newProject);
      await dbService.updateDocument("quotations", q.id, { status: "Jadi Proyek" });
      await logActivity(
        "PROJECT",
        "CREATE",
        `Membuat proyek otomatis: ${newProject.name} dari Surat Penawaran No: ${q.number}`
      );

      setToastMessage("Proyek SPK Baru Berhasil Diluncurkan!");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2050);
      navigate("admin-projects");
    } catch (err) {
      console.error("Convert quotation to project error:", err);
      alert("Gagal mengonversi penawaran menjadi proyek.");
    }
  };

