  const handleUpdateProjectContractInfo = async (
    projectId: string,
    contractData: {
      contractNo?: string;
      client?: string;
      contractValue?: number;
      startDate?: string;
      endDate?: string;
    }
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const payload: Partial<Project> = {};
      if (contractData.contractValue !== undefined) payload.contractValue = contractData.contractValue;
      if (contractData.startDate !== undefined) payload.startDate = contractData.startDate;
      if (contractData.endDate !== undefined) payload.endDate = contractData.endDate;
      if (contractData.client !== undefined) (payload as any).client = contractData.client;

      await dbService.updateDocument("projects", projectId, payload);

      const updatedProj = { ...p, ...payload };
      setProjects((prev) =>
        prev.map((pr) => (pr.id === projectId ? updatedProj : pr))
      );
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProj);
      }

      // Sync linked DebtRecord in `debtRecords`
      const linkedDebt = debtRecords.find(
        (d) =>
          (d.type === "PIUTANG" && d.projectId === projectId) ||
          (d.type === "PIUTANG" &&
            d.title &&
            p.name &&
            (d.title.toLowerCase().includes(p.name.toLowerCase()) ||
              p.name.toLowerCase().includes(d.title.toLowerCase()))) ||
          (d.type === "PIUTANG" && d.customId && d.customId === projectId)
      );

      if (linkedDebt) {
        const debtPayload: any = {};
        if (contractData.contractValue !== undefined) debtPayload.amount = contractData.contractValue;
        if (contractData.client !== undefined) debtPayload.contactName = contractData.client;
        if (contractData.contractNo !== undefined) debtPayload.customId = contractData.contractNo;

        if (Object.keys(debtPayload).length > 0) {
          await dbService.updateDocument("debtRecords", linkedDebt.id, debtPayload);
          setDebtRecords((prev) =>
            prev.map((d) => (d.id === linkedDebt.id ? { ...d, ...debtPayload } : d))
          );
        }
      }

      setToastMessage("Informasi Kontrak & Proyek berhasil diperbarui");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Error updating project contract info:", err);
    }
  };

  const handleToggleProjectActive = async (proj: Project) => {
    const currentlyActive = isProjectActive(proj);
    const nextActive = !currentlyActive;
    const nextStatus = nextActive
      ? (proj.status === "Nonaktif" || proj.status === "Closed" || proj.status === "Completed" || proj.status === "Ditolak"
          ? "Pelaksanaan"
          : proj.status || "Pelaksanaan")
      : "Nonaktif";

    const newTimelineRecord = {
      id: `TL-${Date.now()}`,
      date: new Date().toISOString().split("T")[0],
      time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
      user: currentUser?.name || "Admin",
      status: nextStatus,
      notes: nextActive
        ? "Mengaktifkan status operasional proyek."
        : "Menonaktifkan / menangguhkan status proyek.",
    };

    const updatedTimeline = [...(proj.timeline || []), newTimelineRecord];

    try {
      const payload: Partial<Project> = {
        isActive: nextActive,
        status: nextStatus,
        timeline: updatedTimeline,
      };

      await dbService.updateDocument("projects", proj.id, payload);

      const updatedProject: Project = {
        ...proj,
        isActive: nextActive,
        status: nextStatus,
        timeline: updatedTimeline,
      };

      setProjects((prev) =>
        prev.map((pr) => (pr.id === proj.id ? updatedProject : pr))
      );
      if (projectToManage?.id === proj.id) {
        setProjectToManage(updatedProject);
      }

      setToastMessage(
        nextActive
          ? `Proyek "${proj.name}" berhasil diaktifkan`
          : `Proyek "${proj.name}" berhasil dinonaktifkan`
      );
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Error toggling project active status:", err);
      alert("Gagal mengubah status aktif proyek.");
    }
  };

