      const payload: Partial<Project> = {
        contractValue,
        paymentTerms: updatedTerms,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = { ...p, contractValue, paymentTerms: updatedTerms };
      
      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }
      setToastMessage("Nilai kontrak berhasil diperbarui");
