  const handleApproveProjectDocument = async (
    projectId: string,
    docId: string
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const updatedDocs = (p.uploadedDocuments || []).map((doc) => {
        if (doc.id === docId) {
          return { ...doc, status: "Approved" as const };
        }
        return doc;
      });

      const approvedDoc = (p.uploadedDocuments || []).find((d) => d.id === docId);
      let nextStatus = p.status;
      let updatedTimeline = p.timeline || [];

      if (approvedDoc && approvedDoc.type === "BAST") {
        nextStatus = "Serah Terima";
        const newRecord = {
          id: `TL-${Date.now()}`,
          date: new Date().toISOString().split("T")[0],
          time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
          user: "Sistem",
          status: "Serah Terima",
          notes: "Dokumen BAST telah disetujui. Status proyek otomatis beralih ke Serah Terima.",
        };
        updatedTimeline = [...updatedTimeline, newRecord];
      }

      const payload: Partial<Project> = {
        uploadedDocuments: updatedDocs,
        status: nextStatus,
        timeline: updatedTimeline,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = {
        ...p,
        uploadedDocuments: updatedDocs,
        status: nextStatus,
        timeline: updatedTimeline,
      };
      
      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }
      setToastMessage(`Status dokumen diperbarui.`);
      setShowToast(true);
    } catch (err) {
      console.error("Error approving document:", err);
    }
  };

