  const handleAddProjectPaymentTerm = async (
    projectId: string,
    name: string,
    percentage: number,
    extraOptions?: {
      description?: string;
      dueDate?: string;
      invoiceDate?: string;
      amountCustom?: number;
    }
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const isPpn = p.hasPpn !== false;
      const baseVal = p.contractValue || 0;
      const grossVal = isPpn ? Math.round(baseVal * 1.11) : baseVal;
      const calculatedAmount = extraOptions?.amountCustom && extraOptions.amountCustom > 0
        ? extraOptions.amountCustom
        : Math.round((percentage / 100) * grossVal);

      const newTermId = `TRM-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
      const newTerm = {
        id: newTermId,
        name,
        percentage,
        amount: calculatedAmount,
        description: extraOptions?.description || name,
        dueDate: extraOptions?.dueDate || "-",
        invoiceDate: extraOptions?.invoiceDate || "-",
        paymentDate: "-",
        status: "Belum Dibuat" as const,
      };

      const updatedTerms = [...(p.paymentTerms || []), newTerm];
      const payload: Partial<Project> = {
        paymentTerms: updatedTerms,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = { ...p, paymentTerms: updatedTerms };
      
      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }

      // Sync to debtRecords
      const matchingDebt = debtRecords.find(
        (d) =>
          d.type === "PIUTANG" &&
          (d.projectId === projectId ||
            d.id === `PTG-PROJ-${projectId}` ||
            (d.title && p.name && (d.title.toLowerCase().includes(p.name.toLowerCase()) || p.name.toLowerCase().includes(d.title.toLowerCase()))))
      );

      const formattedNewTerm = {
        id: newTerm.id,
        name: newTerm.name,
        description: newTerm.description,
        amount: newTerm.amount,
        expectedAmount: newTerm.amount,
        percentage: newTerm.percentage,
        invoiceDate: newTerm.invoiceDate,
        dueDate: newTerm.dueDate,
        paymentDate: "-",
        status: "BELUM BAYAR" as const,
        notes: "-"
      };

      if (matchingDebt) {
        const debtTerms = (matchingDebt.terms || []).map((t: any) => ({ ...t }));
        debtTerms.push(formattedNewTerm);

        const updatedDebtPayload = {
          ...matchingDebt,
          terms: debtTerms
        };

        await dbService.setDocument("debtRecords", matchingDebt.id, updatedDebtPayload);
        setDebtRecords(prev => prev.map(d => d.id === matchingDebt.id ? updatedDebtPayload : d));
      } else {
        const newDebtId = `PTG-PROJ-${projectId}`;
        const newDebtRecord: DebtRecord = {
          id: newDebtId,
          customId: (p as any).customId || `PTG-${projectId.slice(-6)}`,
          projectId: p.id,
          type: "PIUTANG",
          title: p.name,
          contactName: p.client || `Client ${p.name}`,
          amount: grossVal,
          dueDate: p.endDate ? (isNaN(Number(p.endDate)) ? p.endDate : new Date(Number(p.endDate)).toISOString().split('T')[0]) : new Date().toISOString().split('T')[0],
          status: "UNPAID",
          description: `Rekam Piutang & Termin Proyek ${p.name}`,
          recordedBy: currentUser?.name || "Admin",
          timestamp: Date.now(),
          terms: [formattedNewTerm],
          payments: []
        };
        await dbService.setDocument("debtRecords", newDebtId, newDebtRecord);
        setDebtRecords(prev => [newDebtRecord, ...prev]);
      }

      setToastMessage(`Termin pembayaran "${name}" berhasil dibuat.`);
      setShowToast(true);
    } catch (err) {
      console.error("Error adding payment term:", err);
    }
  };

  const applyTermPreset = async (
    projectId: string,
    presetTerms: Array<{ name: string; percentage: number; description?: string; dueDate?: string }>
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const isPpn = p.hasPpn !== false;
      const baseVal = p.contractValue || 0;
      const grossVal = isPpn ? Math.round(baseVal * 1.11) : baseVal;

      const newPaymentTerms = presetTerms.map((t, idx) => {
        const calculatedAmount = Math.round((t.percentage / 100) * grossVal);
        return {
          id: `TRM-${Date.now()}-${idx + 1}`,
          name: t.name,
          percentage: t.percentage,
          amount: calculatedAmount,
          description: t.description || t.name,
          dueDate: t.dueDate || "-",
          invoiceDate: "-",
          paymentDate: "-",
          status: "Belum Dibuat" as const,
        };
      });

      await dbService.updateDocument("projects", projectId, { paymentTerms: newPaymentTerms });
      const updatedProject = { ...p, paymentTerms: newPaymentTerms };

      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }

      // Sync to debtRecords
      const matchingDebt = debtRecords.find(
        (d) =>
          d.type === "PIUTANG" &&
          (d.projectId === projectId ||
            d.id === `PTG-PROJ-${projectId}` ||
            (d.title && p.name && (d.title.toLowerCase().includes(p.name.toLowerCase()) || p.name.toLowerCase().includes(d.title.toLowerCase()))))
      );

      const formattedDebtTerms = newPaymentTerms.map((t) => ({
        id: t.id,
        name: t.name,
        description: t.description,
        amount: t.amount,
        expectedAmount: t.amount,
        percentage: t.percentage,
        invoiceDate: "-",
        dueDate: t.dueDate,
        paymentDate: "-",
        status: "BELUM BAYAR" as const,
        notes: "-"
      }));

      if (matchingDebt) {
        const updatedDebtPayload = {
          ...matchingDebt,
          terms: formattedDebtTerms
        };
        await dbService.setDocument("debtRecords", matchingDebt.id, updatedDebtPayload);
        setDebtRecords(prev => prev.map(d => d.id === matchingDebt.id ? updatedDebtPayload : d));
      } else {
        const newDebtId = `PTG-PROJ-${projectId}`;
        const newDebtRecord: DebtRecord = {
          id: newDebtId,
          customId: (p as any).customId || `PTG-${projectId.slice(-6)}`,
          projectId: p.id,
          type: "PIUTANG",
          title: p.name,
          contactName: p.client || `Client ${p.name}`,
          amount: grossVal,
          dueDate: p.endDate ? (isNaN(Number(p.endDate)) ? p.endDate : new Date(Number(p.endDate)).toISOString().split('T')[0]) : new Date().toISOString().split('T')[0],
          status: "UNPAID",
          description: `Rekam Piutang & Termin Proyek ${p.name}`,
          recordedBy: currentUser?.name || "Admin",
          timestamp: Date.now(),
          terms: formattedDebtTerms,
          payments: []
        };
        await dbService.setDocument("debtRecords", newDebtId, newDebtRecord);
        setDebtRecords(prev => [newDebtRecord, ...prev]);
      }

      setToastMessage(`Skema termin berhasil diterapkan (${presetTerms.length} termin).`);
      setShowToast(true);
    } catch (err) {
      console.error("Error applying term preset:", err);
    }
  };

  const handleRemoveProjectPaymentTerm = async (
    projectId: string,
    termId?: string,
    termIndex?: number,
    termObj?: any
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const targetDebt = debtRecords.find(
        (d) =>
          d.type === "PIUTANG" &&
          (d.projectId === projectId ||
            (d.customId && (d.customId === projectId || (p.customId && d.customId === p.customId))) ||
            d.id === `PTG-PROJ-${projectId}` ||
            (d.title && p.name && (d.title.toLowerCase().includes(p.name.toLowerCase()) || p.name.toLowerCase().includes(d.title.toLowerCase()))))
      );

      // Get current active terms list (if project.paymentTerms is defined, use it; otherwise fallback to debt.terms)
      const currentTerms = (p.paymentTerms !== undefined && p.paymentTerms !== null)
        ? p.paymentTerms
        : (targetDebt?.terms || []);

      const updatedTerms = currentTerms.filter((t: any, idx: number) => {
        if (termId && t.id && t.id === termId) return false;
        if (termObj?.id && t.id && t.id === termObj.id) return false;
        if (termObj?.customId && t.customId && t.customId === termObj.customId) return false;
        if (termObj?.name && t.name && t.name === termObj.name) return false;
        if (termIndex !== undefined && termIndex !== null && idx === termIndex) return false;
        return true;
      });

      const payload: Partial<Project> = {
        paymentTerms: updatedTerms,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = { ...p, paymentTerms: updatedTerms };
      
      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }

      // Sync to targetDebt in debtRecords
      if (targetDebt) {
        const debtTerms = (targetDebt.terms && targetDebt.terms.length > 0) ? targetDebt.terms : currentTerms;
        const updatedDebtTerms = debtTerms.filter((t: any, idx: number) => {
          if (termId && t.id && t.id === termId) return false;
          if (termObj?.id && t.id && t.id === termObj.id) return false;
          if (termObj?.customId && t.customId && t.customId === termObj.customId) return false;
          if (termObj?.name && t.name && t.name === termObj.name) return false;
          if (termIndex !== undefined && termIndex !== null && idx === termIndex) return false;
          return true;
        });

        const updatedDebtPayload = {
          ...targetDebt,
          terms: updatedDebtTerms
        };

        await dbService.setDocument("debtRecords", targetDebt.id, updatedDebtPayload);
        setDebtRecords(prev => prev.map(d => d.id === targetDebt.id ? updatedDebtPayload : d));
      }

      setToastMessage("Termin pembayaran berhasil dihapus.");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Error removing payment term:", err);
      alert("Gagal menghapus termin pembayaran.");
    }
  };

  const handleCreateTermInvoice = async (
    projectId: string,
    termId: string
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const foundTerm = (p.paymentTerms || []).find((t) => t.id === termId);
      if (!foundTerm) return;

      const defaultInvNum = `INV/${new Date().getFullYear()}/${Math.floor(1000 + Math.random() * 9000)}`;
      const userInvNum = prompt("Masukkan Nomor Invoice secara manual untuk termin ini:", defaultInvNum);
      if (userInvNum === null) return; // User cancelled
      const invNum = userInvNum.trim() || defaultInvNum;

      const invId = `INV-${Math.floor(1000 + Math.random() * 9000)}`;
      
      const itemsArray = [
        {
          description: `Tagihan Termin: ${foundTerm.name} - Pekerjaan: ${p.name}`,
          qty: 1,
          unit: "Termin",
          price: foundTerm.amount,
        }
      ];

      const newInvoice = {
        id: invId,
        invoiceNumber: invNum,
        clientId: p.managerId || "",
        clientName: p.name + " Client",
        projectId: p.id,
        amount: foundTerm.amount,
        fee: 0,
        tax: 0,
        total: foundTerm.amount,
        status: "PENDING" as const,
        dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().split("T")[0],
        createdAt: new Date().toISOString(),
        itemsJson: JSON.stringify(itemsArray),
        jobName: p.name,
      };

      await dbService.setDocument("invoices", invId, newInvoice);

      const updatedTerms = (p.paymentTerms || []).map((term) => {
        if (term.id === termId) {
          return {
            ...term,
            status: "Menunggu Pembayaran" as const,
            invoiceNumber: invNum,
            invoiceId: invId,
          };
        }
        return term;
      });

      const newTimelineRecord = {
        id: `TL-${Date.now()}`,
        date: new Date().toISOString().split("T")[0],
        time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
        user: "Sistem",
        status: p.status,
        notes: `Menerbitkan invoice ${invNum} untuk tagihan termin "${foundTerm.name}" senilai Rp ${foundTerm.amount.toLocaleString("id-ID")}`,
      };

      const updatedTimeline = [...(p.timeline || []), newTimelineRecord];

      const payload: Partial<Project> = {
        paymentTerms: updatedTerms,
        timeline: updatedTimeline,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = {
        ...p,
        paymentTerms: updatedTerms,
        timeline: updatedTimeline,
      };

      setInvoices(prev => [...prev, newInvoice]);

      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }
      setToastMessage(`Invoice ${invNum} diterbitkan untuk termin ini.`);
      setShowToast(true);
    } catch (err) {
      console.error("Error creating term invoice:", err);
    }
  };

  const handlePayTermInvoice = async (
    projectId: string,
    termId: string
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const foundTerm = (p.paymentTerms || []).find((t) => t.id === termId);
      if (!foundTerm) return;

      const invoiceId = foundTerm.invoiceId;
      if (invoiceId) {
        await dbService.updateDocument("invoices", invoiceId, { status: "PAID" });
        setInvoices(prev => prev.map((inv) => inv.id === invoiceId ? { ...inv, status: "PAID" } : inv));
      }

      const updatedTerms = (p.paymentTerms || []).map((term) => {
        if (term.id === termId) {
          return {
            ...term,
            status: "Dibayar" as const,
          };
        }
        return term;
      });

      const totalPaidValue = updatedTerms
        .filter((t) => t.status === "Dibayar")
        .reduce((sum, t) => sum + t.amount, 0);

      let nextStatus = p.status;
      let updatedTimeline = p.timeline || [];

      const totalTermsCount = updatedTerms.length;
      const paidTermsCount = updatedTerms.filter((t) => t.status === "Dibayar").length;
      
      const isFullyPaid = totalTermsCount > 0 && paidTermsCount === totalTermsCount;

      if (isFullyPaid && p.status === "Menunggu Pelunasan") {
        nextStatus = "Lunas";
        const newRecord = {
          id: `TL-${Date.now()}`,
          date: new Date().toISOString().split("T")[0],
          time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
          user: "Sistem",
          status: "Lunas",
          notes: "Seluruh tagihan termin telah lunas dibayar. Status otomatis beralih ke Lunas.",
        };
        updatedTimeline = [...updatedTimeline, newRecord];
      }

      const paymentNotificationRecord = {
        id: `TL-PAY-${Date.now()}`,
        date: new Date().toISOString().split("T")[0],
        time: new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" }),
        user: currentUser?.name || "Admin",
        status: nextStatus,
        notes: `Menerima pembayaran tagihan termin "${foundTerm.name}" senilai Rp ${foundTerm.amount.toLocaleString("id-ID")}`,
      };
      
      updatedTimeline = [...updatedTimeline, paymentNotificationRecord];

      const payload: Partial<Project> = {
        paymentTerms: updatedTerms,
        status: nextStatus,
        timeline: updatedTimeline,
        totalPaid: totalPaidValue,
        remainingReceivables: (p.contractValue || 0) - totalPaidValue,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = {
        ...p,
        paymentTerms: updatedTerms,
        status: nextStatus,
        timeline: updatedTimeline,
        totalPaid: totalPaidValue,
        remainingReceivables: (p.contractValue || 0) - totalPaidValue,
      };

      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }
      setToastMessage(`Termin "${foundTerm.name}" berhasil ditandai Lunas.`);
      setShowToast(true);
    } catch (err) {
      console.error("Error paying term invoice:", err);
    }
  };

  const handleUpdateWarrantyDate = async (
    projectId: string,
    warrantyEndDate: string
  ) => {
    try {
      const p = projects.find((pro) => pro.id === projectId);
      if (!p) return;

      const payload: Partial<Project> = {
        warrantyEndDate,
      };

      await dbService.updateDocument("projects", projectId, payload);
      const updatedProject = { ...p, warrantyEndDate };
      
      setProjects(prev => prev.map((pr) => pr.id === projectId ? updatedProject : pr));
      if (projectToManage?.id === projectId) {
        setProjectToManage(updatedProject);
      }
      setToastMessage("Tanggal masa garansi diperbarui");
      setShowToast(true);
    } catch (err) {
      console.error("Error updating warranty date:", err);
    }
  };

  const handleGeocode = async (
    locationName: string,
    target: "new" | "manage",
  ) => {
    if (!locationName.trim()) return;
    setIsGeocoding(true);
    try {
      // Logic for Parsing Google Maps URL
      const urlMatch = locationName.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/);
      if (urlMatch) {
        const lat = parseFloat(urlMatch[1]);
        const lon = parseFloat(urlMatch[2]);

        if (target === "new") {
          setNewProjectLat(lat.toString());
          setNewProjectLng(lon.toString());
        } else if (target === "manage" && projectToManage) {
          handleUpdateProjectCoordinates(projectToManage.id, lat, lon);
        }

        setToastMessage("Link Maps Berhasil! GPS Terdeteksi.");
        setShowToast(true);
        setTimeout(() => setShowToast(false), 3000);
        return;
      }

      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(locationName)}&limit=1`,
      );
      const data = await response.json();
      if (data && data.length > 0) {
        const lat = parseFloat(data[0].lat);
        const lon = parseFloat(data[0].lon);

        if (target === "new") {
          setNewProjectLat(lat.toString());
          setNewProjectLng(lon.toString());
        } else if (target === "manage" && projectToManage) {
          handleUpdateProjectCoordinates(projectToManage.id, lat, lon);
        }

        setToastMessage("Koordinat berhasil sinkron!");
        setShowToast(true);
        setTimeout(() => setShowToast(false), 3000);
      } else {
        alert("Lokasi tidak ditemukan. Silakan isi koordinat secara manual.");
      }
    } catch (err) {
      console.error("Geocoding error:", err);
      alert("Gagal mengambil data lokasi. Silakan cek koneksi internet.");
    } finally {
      setIsGeocoding(false);
    }
  };

  const handleUpdateProjectCoordinates = async (
    projectId: string,
    lat: number,
    lng: number,
  ) => {
    try {
      await dbService.updateDocument("projects", projectId, { lat, lng });
      if (projectToManage?.id === projectId) {
        setProjectToManage({ ...projectToManage, lat, lng });
      }
      setToastMessage("Koordinat berhasil diperbarui");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Update coordinates error:", err);
    }
  };

  const handleRequestAction = async (
    reqId: string,
    type: string,
    action: "Approved" | "Rejected",
  ) => {
    try {
      const collectionName =
        type === "Cuti / Izin"
          ? "leaveRequests"
          : type === "Reimbursement"
            ? "reimbursements"
            : "cashAdvances";

      const requests =
        type === "Cuti / Izin"
          ? leaveRequests
          : type === "Reimbursement"
            ? reimbursements
            : cashAdvances;
      const request = requests.find((r: any) => r.id === reqId);

      await dbService.updateDocument(collectionName, reqId, { status: action });

      await logActivity(
        "APPROVAL",
        action.toUpperCase(),
        `${action === "Approved" ? "Menyetujui" : "Menolak"} permintaan ${type} dari ${request?.userName || "Karyawan"}${request?.amount ? ` senilai Rp ${request.amount.toLocaleString("id-ID")}` : ""}`,
      );

      if (request) {
        const title = `Pengajuan ${type} ${action === "Approved" ? "Disetujui" : "Ditolak"}`;
        const message = `Halo ${request.userName || "Karyawan"}, pengajuan ${type} Anda telah ${action === "Approved" ? "disetujui" : "ditolak"} oleh pihak manajemen.`;
        await dbService.createDocument("notifications", {
          title,
          message,
          type: action === "Approved" ? "SUCCESS" : "ALERT",
          category: type === "Cuti / Izin" ? "Absensi" : "Finance",
          read: false,
          userId: request.userId || request.employeeId || "ALL",
          createdAt: Date.now(),
        });
      }

      setToastMessage(
        `Permintaan ${action === "Approved" ? "disetujui" : "ditolak"}`,
      );
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Action error:", err);
      alert("Gagal memproses permintaan.");
    }
  };

