  const handleSaveQuotation = async (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);

    let subTotal = 0;
    let tax = 0;
    let grandTotal = 0;
    let finalItems: QuotationItem[] = [];

    if (isAttachmentOnlyMode) {
      if (!uploadedFileInfo) {
        alert("Harap unggah berkas surat penawaran Anda terlebih dahulu.");
        return;
      }
      if (manualGrandTotal <= 0) {
        alert("Harap masukkan Total Nilai Penawaran (Rupiah) yang valid.");
        return;
      }

      grandTotal = manualGrandTotal;
      if (manualIncludePPN) {
        subTotal = Math.round(grandTotal / 1.11);
        tax = grandTotal - subTotal;
      } else {
        subTotal = grandTotal;
        tax = 0;
      }

      finalItems = [
        {
          id: `item-attachment-${Date.now()}`,
          description: `Pekerjaan sesuai berkas lampiran SPH: ${uploadedFileInfo.name}`,
          vol: 1,
          unit: "Lot",
          unitPrice: subTotal,
          total: subTotal,
        }
      ];
    } else {
      finalItems = quotationItems
        .filter((item) => item.description?.trim())
        .map((item, index) => {
          const total = (item.vol || 0) * (item.unitPrice || 0);
          subTotal += total;
          return {
            id: item.id || `item-${Date.now()}-${index}`,
            description: item.description || "",
            vol: item.vol || 0,
            unit: item.unit || "",
            unitPrice: item.unitPrice || 0,
            total: total,
          };
        });

      if (finalItems.length === 0) {
        alert("Harap masukkan minimal satu item pekerjaan.");
        return;
      }

      tax = Math.round(subTotal * 0.11);
      grandTotal = subTotal + tax;
    }

    const id = viewingQuotation?.id || `QT-${Date.now()}`;
    const newQuotation: Quotation = {
      id,
      number: formData.get("number") as string,
      date: formData.get("date") as string,
      recipient: formData.get("recipient") as string,
      attention: formData.get("attention") as string,
      jobDescription: formData.get("jobDescription") as string,
      items: finalItems,
      subTotal,
      tax,
      grandTotal,
      notes:
        (formData.get("notes") as string) || " - Harga belum termasuk PPN 11%",
      preparedBy: currentUser?.name || "Admin",
      userId: currentUser?.id,
      createdAt: viewingQuotation?.createdAt || Date.now(),
      boqProjectId: quoteBoqId || "",
      status: viewingQuotation?.status || "Draft",
      attachmentName: uploadedFileInfo?.name || viewingQuotation?.attachmentName || "",
      attachmentBase64: uploadedFileBase64 || viewingQuotation?.attachmentBase64 || "",
    };

    try {
      await dbService.setDocument("quotations", id, newQuotation);
      setIsQuotationModalOpen(false);
      setViewingQuotation(null);
      setQuotationItems([]);
      setUploadedFileInfo(null);
      setUploadedFileBase64("");
      setAiQuoteText("");
      setToastMessage("Surat Penawaran berhasil disimpan");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2000);

      // Open interactive PDF preview modal instead of immediate auto-download
      setPreviewQuotationData({ ...newQuotation, id });
      setIsPreviewOpenApp(true);
    } catch (err) {
      console.error("Save quotation error:", err);
      alert("Gagal menyimpan penawaran.");
    }
  };

