  const handleAssignEmployeeToProject = async (
    employeeId: string,
    projectId: string,
    rate?: number,
  ) => {
    try {
      const employee = employees.find((e) => e.id === employeeId);
      if (!employee) return;

      const isAlreadyAssigned = (employee.assignedProjectIds || []).length > 0;
      if (isAlreadyAssigned) {
        const confirmNeeded = window.confirm(
          `${employee.name} sudah terdaftar di projek lain. Apakah Anda yakin orang ini sangat dibutuhkan di projek ini?`,
        );
        if (!confirmNeeded) return;
      }

      const assignedProjectIds = [...(employee.assignedProjectIds || [])];
      if (!assignedProjectIds.includes(projectId)) {
        assignedProjectIds.push(projectId);
      }

      const updates: any = { assignedProjectIds };
      if (rate !== undefined) {
        const projectRates = { ...((employee as any).projectRates || {}) };
        projectRates[projectId] = rate;
        updates.projectRates = projectRates;
      }

      await dbService.updateDocument("users", employeeId, updates);

      // Update local state if needed (snapshot will handle most cases)
    } catch (err) {
      console.error("Assign employee error:", err);
      alert("Gagal menambahkan karyawan ke projek.");
    }
  };

  const handleRemoveEmployeeFromProject = async (
    employeeId: string,
    projectId: string,
  ) => {
    try {
      const employee = employees.find((e) => e.id === employeeId);
      if (!employee) return;

      const assignedProjectIds = (employee.assignedProjectIds || []).filter(
        (id) => id !== projectId,
      );

      const updates: any = { assignedProjectIds };
      // Optionally keep the rate or remove it

      await dbService.updateDocument("users", employeeId, updates);
    } catch (err) {
      console.error("Remove employee error:", err);
    }
  };

  const handleMoveStaffToProject = async (
    employeeId: string,
    fromProjectId: string,
    toProjectId: string,
  ) => {
    try {
      const employee = employees.find((e) => e.id === employeeId);
      if (!employee || !toProjectId) return;

      const assignedProjectIds = (employee.assignedProjectIds || []).filter(
        (id) => id !== fromProjectId,
      );
      if (!assignedProjectIds.includes(toProjectId)) {
        assignedProjectIds.push(toProjectId);
      }

      await dbService.updateDocument("users", employeeId, {
        assignedProjectIds,
      });
      setMovingStaffId(null);
      setMovingToProjectId("");
      setToastMessage("Karyawan berhasil dipindah projek");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } catch (err) {
      console.error("Move staff error:", err);
      alert("Gagal memindahkan karyawan.");
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const username = (formData.get("username") as string).trim();
    const phone = formData.get("phone") as string;
    const password = formData.get("password") as string;
    const bagian = formData.get("bagian") as string;

    if (
      username.toLowerCase() === "admgigt" ||
      username.toLowerCase() === "admin"
    ) {
      alert("ID ini diproteksi oleh sistem. Silakan gunakan ID lain.");
      return;
    }

    if (password.length < 6) {
      alert("Kata sandi harus minimal 6 karakter!");
      return;
    }

    try {
      // Improve email generation to handle cases where username is already an email
      let signupEmail = username.toLowerCase();
      if (!signupEmail.includes("@")) {
        signupEmail = `${username.replace(/\s+/g, "").toLowerCase()}@workflowpro.com`;
      }

      const userCredential = await createUserWithEmailAndPassword(
        auth,
        signupEmail,
        password,
      );
      const user = userCredential.user;

      const isAdminEmail =
        signupEmail === "admgigt@workflowpro.com" ||
        signupEmail === "alexsanderjafra@gmail.com";

      const userData = {
        username: username.toLowerCase().includes("@")
          ? username.split("@")[0]
          : username,
        phone,
        bagian,
        name: username,
        email: signupEmail,
        password, // Storing for legacy reasons as the app was built this way
        role: isAdminEmail ? "admin" : "staff",
        dailyRate: isAdminEmail ? 300000 : 150000,
        createdAt: Date.now(),
        isAdmin: isAdminEmail,
      };

      await dbService.setDocument("users", user.uid, userData);
      const loggedUser = { ...userData, id: user.uid };
      setCurrentUser(loggedUser);
      localStorage.setItem("workflow_pro_user", JSON.stringify(loggedUser));
      alert("Akun berhasil dibuat!");
      if (loggedUser.role === "admin") {
        navigate("admin-dashboard", loggedUser);
      } else {
        navigate("home", loggedUser);
      }
    } catch (error: any) {
      console.error("Registration error:", error);
      const errorMessage = error.message || String(error);
      if (error.code === "auth/operation-not-allowed") {
        alert(
          "Metode Registrasi Email/Password belum diaktifkan di Firebase Console. \n\nSilakan buka: https://console.firebase.google.com/project/gen-lang-client-0369794089/authentication/providers \nlalu aktifkan 'Email/Password'.",
        );
      } else if (error.code === "auth/too-many-requests") {
        alert(
          "Terlalu banyak permintaan untuk registrasi. Silakan coba lagi beberapa saat lagi.",
        );
      } else if (
        error.code === "auth/email-already-in-use" ||
        errorMessage.includes("email-already-in-use")
      ) {
        alert(
          "ID atau Email ini sudah terdaftar! Silakan gunakan ID lain atau hubungi admin.",
        );
      } else if (error.code === "auth/weak-password") {
        alert("Kata sandi terlalu lemah. Gunakan minimal 6 karakter.");
      } else if (error.code === "auth/invalid-credential") {
        alert("Kredensial tidak valid untuk registrasi.");
      } else {
        alert("Registrasi gagal: " + errorMessage);
      }
    }
  };

