  const handleLeaveSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget as HTMLFormElement);
    const formType = formData.get("formType") as "IZIN" | "CUTI";

    const request: any = {
      userId: currentUser?.id || currentUser?.username || "unknown",
      type: formType,
      name: currentUser?.name || "Karyawan",
      status: "Pending",
      timestamp: Date.now(),
      reason: formData.get("reason") as string,
    };

    if (formType === "IZIN") {
      request.date = formData.get("date") as string;
      request.startTime = formData.get("startTime") as string;
      request.endTime = formData.get("endTime") as string;
    } else {
      request.startDate = formData.get("startDate") as string;
      request.endDate = formData.get("endDate") as string;
      request.date = formData.get("submitDate") as string;
    }

    await dbService.createDocument("leaveRequests", request);
    await dbService.createDocument("notifications", {
      title: `Pengajuan ${formType === "IZIN" ? "Izin Setengah Hari" : "Cuti"} Baru`,
      message: `${request.name} mengajukan ${formType === "IZIN" ? "izin" : "cuti"} untuk keperluan: ${request.reason}.`,
      type: "INFO",
      category: "Absensi",
      read: false,
      userId: "ADMIN_OWNER",
      createdAt: Date.now(),
    });

    setShowToast(true);
    setToastMessage("Pengajuan izin/cuti berhasil terkirim!");
    setTimeout(() => setShowToast(false), 2000);
    setLeaveFormType(null);
    navigate("home");
  };

  const handleDeleteLeaveRequest = async (id: string) => {
    if (!id) return;
    if (!window.confirm("Apakah Anda yakin ingin menghapus pengajuan izin/cuti ini secara permanen?")) {
      return;
    }
    try {
      await dbService.deleteDocument("leaveRequests", id);
      setToastMessage("Pengajuan izin/cuti berhasil dihapus!");
      setShowToast(true);
      setTimeout(() => setShowToast(false), 2000);
    } catch (err) {
      console.error("Gagal menghapus pengajuan izin/cuti:", err);
      alert("Gagal menghapus pengajuan. Silakan coba lagi.");
    }
  };

  const [leaveFormType, setLeaveFormType] = useState<"IZIN" | "CUTI" | null>(
    null,
  );

  // Sorted reports memoized
  const sortedReports = useMemo(() => {
    const priorityOrder = { High: 3, Medium: 2, Low: 1 };
    const statusOrder = { APPROVED: 3, PENDING: 2, PROSES: 1 };

    return [...reports].sort((a, b) => {
      if (sortBy === "priority") {
        return (
          (priorityOrder[b.priority] || 0) - (priorityOrder[a.priority] || 0)
        );
      }
      if (sortBy === "status") {
        return (statusOrder[b.status] || 0) - (statusOrder[a.status] || 0);
      }
      // For 'time', we stick to the creation order (newest first)
      return 0;
    });
  }, [reports, sortBy]);

  // Helper to check if attendance is from the current work day (resets at 5 AM)
  const isAttendanceFromToday = (timestamp: number) => {
    const now = new Date();
    const resetHour = 5; // Reset at 5 AM

    const lastReset = new Date(now);
    if (now.getHours() < resetHour) {
      lastReset.setDate(now.getDate() - 1);
    }
    lastReset.setHours(resetHour, 0, 0, 0);

    return timestamp > lastReset.getTime();
  };

