  // Auto-sync projects to debtRecords so every project automatically appears under Piutang in Menu Hutang Piutang
  useEffect(() => {
    if (currentUser && isFinanceLoaded && projects.length > 0) {
      const unlinkedProjects = projects.filter((p) => {
        const pNameLower = (p.name || "").toLowerCase().trim();
        if (!pNameLower) return false;
        return !debtRecords.some((r) => {
          if (r.type !== "PIUTANG") return false;
          if (r.projectId && r.projectId === p.id) return true;
          if (r.customId && r.customId === p.id) return true;
          const rTitleLower = (r.title || "").toLowerCase().trim();
          return rTitleLower && pNameLower && (rTitleLower.includes(pNameLower) || pNameLower.includes(rTitleLower));
        });
      });

      if (unlinkedProjects.length > 0) {
        console.log(`Auto-linking ${unlinkedProjects.length} projects to Piutang debtRecords...`);
        unlinkedProjects.forEach(async (p) => {
          const isPpnEnabled = p.hasPpn !== false;
          const dpp = p.contractValue || 0;
          const totalWithPpn = isPpnEnabled ? Math.round(dpp * 1.11) : dpp;
          const newDebtId = `PTG-PROJ-${p.id}`;
          const customId = p.customId || `PTG-${p.id.slice(-6)}`;

          const newDebt: DebtRecord = {
            id: newDebtId,
            customId: customId,
            projectId: p.id,
            type: "PIUTANG",
            title: p.name,
            contactName: p.client || `Client ${p.name}`,
            amount: totalWithPpn,
            dueDate: p.endDate
              ? (isNaN(Number(p.endDate))
                  ? p.endDate
                  : new Date(Number(p.endDate)).toISOString().split('T')[0])
              : new Date().toISOString().split('T')[0],
            status: "UNPAID",
            description: `Rekam Piutang & Termin Proyek ${p.name}`,
            recordedBy: currentUser?.name || "Admin",
            timestamp: p.createdAt || Date.now(),
            terms: p.paymentTerms
              ? p.paymentTerms.map((t: any, idx: number) => ({
                  name: t.name || `Termin ${idx + 1}`,
                  description: t.name || `Termin ${idx + 1}`,
                  amount: t.amount || 0,
                  expectedAmount: t.amount || 0,
                  percentage: t.percentage || 0,
                  invoiceDate: "-",
                  dueDate: "-",
                  paymentDate: t.status === "Dibayar" ? new Date().toISOString().split('T')[0] : "-",
                  status: t.status === "Dibayar" ? "LUNAS" : "BELUM BAYAR",
                  notes: "-",
                }))
              : [],
            payments: [],
          };

          try {
            await dbService.setDocument("debtRecords", newDebtId, newDebt);
            console.log(`Successfully auto-linked project ${p.name} [${newDebtId}] to debtRecords`);
          } catch (err) {
            console.error(`Failed to auto-link project ${p.name}:`, err);
          }
        });
      }
    }
  }, [currentUser, isFinanceLoaded, projects, debtRecords]);

  // Sync today's attendance status
  useEffect(() => {
    if (!currentUser || attendanceHistory.length === 0) return;

    const userAttendance = attendanceHistory.filter(
      (h) => h.userId === currentUser.id || h.userId === currentUser.username,
    );

    let clockedOutToday = false;
    const todayOut = userAttendance.find(
      (h) => h.type === "OUT" && isAttendanceFromToday(h.timestamp),
    );
    if (todayOut) {
      setIsClockedOut(true);
      setTodayAttendanceOut(todayOut);
      clockedOutToday = true;
      setIsClockedIn(false);
    } else {
      setIsClockedOut(false);
      setTodayAttendanceOut(null);
    }

    if (!clockedOutToday) {
      const todayIn = userAttendance.find(
        (h) => h.type === "IN" && isAttendanceFromToday(h.timestamp),
      );
      if (todayIn) {
        setIsClockedIn(true);
        setTodayAttendance(todayIn);
      } else {
        setIsClockedIn(false);
        setTodayAttendance(null);
      }
    }
  }, [attendanceHistory, currentUser]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

