  const canClockOut = useMemo(() => {
    return !!(isClockedIn && todayAttendance);
  }, [isClockedIn, todayAttendance]);

  const handleClockIn = async () => {
    if (!selfiePreview) {
      alert("Silakan ambil foto selfie terlebih dahulu!");
      return;
    }

    if (!locationTag) {
      alert(
        "Sistem sedang memproses lokasi Anda. Mohon tunggu sesaat sampai peta muncul dan lokasi terkunci.",
      );
      return;
    }

    if (!selectedProjectId && currentUser?.role !== "admin" && currentUser?.role !== "direktur") {
      alert("Silakan pilih projek tempat Anda bertugas terlebih dahulu!");
      return;
    }

    const now = new Date();
    const isLate =
      now.getHours() > 9 || (now.getHours() === 9 && now.getMinutes() > 0);

    if (isLate && !lateReason) {
      setShowLateDialog(true);
      return;
    }

    const project = projects.find((p) => p.id === selectedProjectId);
    const projectDistance =
      project?.lat && project?.lng
        ? calculateDistance(
            locationTag.lat,
            locationTag.lng,
            project.lat,
            project.lng,
          )
        : null;

    const attendanceData = {
      type: "IN",
      userId: currentUser?.id || currentUser?.username || "unknown",
      projectId: selectedProjectId,
      timestamp: Date.now(),
      selfieUrl: selfiePreview,
      lat: locationTag.lat,
      lng: locationTag.lng,
      accuracy: locationTag.accuracy,
      lateReason: lateReason || null,
      projectDistance,
    };

    await dbService.createDocument("attendance", attendanceData);
    setToastMessage("Absensi Masuk Berhasil Diunggah!");
    setIsClockedIn(true);
    setTodayAttendance(attendanceData);
    setSelfiePreview(null);
    setLocationTag(null);
    setLateReason("");
    setShowLateDialog(false);
    setShowToast(true);
    setTimeout(() => {
      setShowToast(false);
      navigate("home");
    }, 1500);
  };

  const handleClockOut = async () => {
    if (!selfiePreview || !locationTag) {
      alert(
        "Silakan ambil foto selfie dan pastikan lokasi sudah terdeteksi terlebih dahulu!",
      );
      return;
    }

    const clockInTime = todayAttendance.timestamp;
    const clockOutTime = Date.now();

    // Calculate overtime: hours worked after 17:00 (5 PM)
    const deadline = new Date(clockOutTime);
    deadline.setHours(17, 0, 0, 0);

    const overtimeMs = Math.max(0, clockOutTime - deadline.getTime());

    // We can also keep the 8-hour duration check for warning purposes
    const durationMs = clockOutTime - clockInTime;
    const eightHoursMs = 8 * 60 * 60 * 1000;

    if (
      durationMs < eightHoursMs &&
      !confirm(
        "Waktu kerja Anda belum mencapai 8 jam. Tetap ingin absen pulang?",
      )
    ) {
      return;
    }

    const project = projects.find(
      (p) => p.id === (todayAttendance?.projectId || ""),
    );
    const projectDistance =
      project?.lat && project?.lng
        ? calculateDistance(
            locationTag.lat,
            locationTag.lng,
            project.lat,
            project.lng,
          )
        : null;

    const attendanceData = {
      type: "OUT",
      userId: currentUser?.id || currentUser?.username || "unknown",
      projectId: todayAttendance.projectId || "",
      timestamp: clockOutTime,
      selfieUrl: selfiePreview,
      lat: locationTag.lat,
      lng: locationTag.lng,
      accuracy: locationTag.accuracy,
      durationMinutes: Math.floor(durationMs / (1000 * 60)),
      overtimeMinutes: Math.floor(overtimeMs / (1000 * 60)),
      projectDistance,
    };

    await dbService.createDocument("attendance", attendanceData);

    setToastMessage("Absensi Pulang Berhasil Diunggah!");
    setIsClockedOut(true);
    setIsClockedIn(false); // Reset clocked in status
    setTodayAttendanceOut(attendanceData);
    setSelfiePreview(null);
    setLocationTag(null);
    setShowToast(true);
    setTimeout(() => {
      setShowToast(false);
      navigate("home");
    }, 1500);
  };

  // Sync effect when back online
