  const captureLocation = () => {
    if (isCapturingLocation) return;

    if ("geolocation" in navigator) {
      setIsCapturingLocation(true);
      if (!locationTag) setLocationTag(null);

      const options = {
        enableHighAccuracy: true,
        timeout: 8000,
        maximumAge: 0,
      };

      const onGeolocationSuccess = (position: GeolocationPosition) => {
        setLocationTag({
          lat: position.coords.latitude,
          lng: position.coords.longitude,
          accuracy: position.coords.accuracy,
        });
        setIsCapturingLocation(false);

        if (position.coords.accuracy > 40) {
          setToastMessage(
            `Lokasi Ditemukan (Akurasi Rendah: ${Math.round(position.coords.accuracy)}m)`,
          );
        } else {
          setToastMessage("Lokasi Berhasil Ditemukan!");
        }
        setShowToast(true);
      };

      const onGeolocationError = (error: GeolocationPositionError) => {
        console.warn("GPS High Accuracy Error:", error.message);

        // Rapid fallback to mixed/low accuracy
        navigator.geolocation.getCurrentPosition(
          onGeolocationSuccess,
          (fallbackError) => {
            setIsCapturingLocation(false);
            let message = "Gagal mengambil lokasi.";
            if (fallbackError.code === 1) message = "Izin lokasi ditolak.";
            else if (fallbackError.code === 2) message = "GPS tidak tersedia.";
            else if (fallbackError.code === 3)
              message = "Waktu habis mencari lokasi.";

            setToastMessage(message);
            setShowToast(true);
          },
          { enableHighAccuracy: false, timeout: 5000, maximumAge: 60000 },
        );
      };

      navigator.geolocation.getCurrentPosition(
        onGeolocationSuccess,
        onGeolocationError,
        options,
      );
    } else {
      setToastMessage("Browser tidak mendukung geolokasi.");
      setShowToast(true);
      setIsCapturingLocation(false);
    }
  };

