  // Session inactivity (2 days timeout) & Mobile Full Screen with double click BACK button to exit
  useEffect(() => {
    const INACTIVITY_LIMIT = 2 * 24 * 60 * 60 * 1000; // 48 hours in ms
    const lastActiveStr = localStorage.getItem("workflow_pro_last_active");

    const checkInactivity = () => {
      if (currentUser) {
        const lastActive = lastActiveStr ? parseInt(lastActiveStr, 10) : Date.now();
        if (Date.now() - lastActive > INACTIVITY_LIMIT) {
          handleLogout();
          alert("Sesi Anda telah berakhir karena tidak ada aktivitas selama 2 hari. Silakan login kembali.");
        }
      }
    };

    // On mount and currentUser load, check immediately
    checkInactivity();

    // Event listener to reset inactivity timer
    const resetInactivityTimer = () => {
      localStorage.setItem("workflow_pro_last_active", Date.now().toString());
    };

    // Register active interactions to update active timestamp
    const interactionEvents = ["click", "keydown", "touchstart", "mousemove"];
    interactionEvents.forEach((event) => {
      window.addEventListener(event, resetInactivityTimer);
    });

    // Mobile Full Screen trigger on user clicking anywhere/links
    const handleMobileFullScreen = () => {
      const isMobile = window.innerWidth < 768 || /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
      if (isMobile && !document.fullscreenElement) {
        document.documentElement.requestFullscreen?.()
          .then(() => {
            const orientation = window.screen && (window.screen.orientation as any);
            if (orientation && orientation.lock) {
              orientation.lock("portrait").catch((err: any) => {
                console.debug("Orientation lock portrait bypassed:", err);
              });
            }
          })
          .catch((err) => {
            console.debug("Fullscreen request bypassed:", err);
          });
      }
    };

    const handleFullscreenChange = () => {
      if (document.fullscreenElement) {
        const orientation = window.screen && (window.screen.orientation as any);
        if (orientation && orientation.lock) {
          orientation.lock("portrait").catch((err: any) => {
            console.debug("Fullscreen change orientation lock bypassed:", err);
          });
        }
      }
    };

    window.addEventListener("click", handleMobileFullScreen);
    window.addEventListener("touchstart", handleMobileFullScreen);
    document.addEventListener("fullscreenchange", handleFullscreenChange);

    return () => {
      interactionEvents.forEach((event) => {
        window.removeEventListener(event, resetInactivityTimer);
      });
      window.removeEventListener("click", handleMobileFullScreen);
      window.removeEventListener("touchstart", handleMobileFullScreen);
      document.removeEventListener("fullscreenchange", handleFullscreenChange);
    };
  }, [currentUser]);

  // Handle Double press Back Button to Exit Application / navigate back to menu home
  useEffect(() => {
    window.history.pushState(null, "", window.location.href);

    let lastBackPress = 0;

    const handlePopState = () => {
      window.history.pushState(null, "", window.location.href);

      const currentTime = Date.now();
      if (currentTime - lastBackPress < 2000) {
        if (document.fullscreenElement) {
          document.exitFullscreen?.().catch(() => {});
        }
        
        if (screen === "home" || screen === "login" || screen === "splash") {
          if (currentUser) {
            handleLogout();
          } else {
            setToastMessage("Menutup aplikasi...");
            setShowToast(true);
            setTimeout(() => setShowToast(false), 2000);
          }
        } else {
          navigate("home");
        }
      } else {
        lastBackPress = currentTime;
        setToastMessage("Klik BACK sekali lagi untuk Keluar / Kembali ke Menu Utama");
        setShowToast(true);
        setTimeout(() => setShowToast(false), 2500);
      }
    };

    window.addEventListener("popstate", handlePopState);
    return () => {
      window.removeEventListener("popstate", handlePopState);
    };
  }, [screen, currentUser]);

