                      <p className="text-[9px] font-bold opacity-70">
                        {isMobileEmployee ? "Bebas Radius (Tugas Luar / Sales)" : `Jarak: ${distance ? (distance * 1000).toFixed(1) : "?"} meter dari site`}
                      </p>
